SELECT * FROM bluesky LIMIT 2;
SELECT COUNT(*) FROM bluesky WHERE data.kind = 'commit';
SELECT data.commit.collection AS event, COUNT(*) AS cnt FROM bluesky GROUP BY event ORDER BY cnt DESC LIMIT 5;
SELECT data.commit.collection AS event, COUNT(*) AS cnt FROM bluesky GROUP BY data.commit.collection ORDER BY cnt DESC LIMIT 5;
SELECT data.commit.collection AS event, COUNT(*) AS cnt, COUNT(DISTINCT data.did) AS users FROM bluesky WHERE data.kind = 'commit' AND data.commit.operation = 'create' GROUP BY event ORDER BY cnt DESC LIMIT 5;
SELECT data.commit.collection AS event, COUNT(*) AS cnt, COUNT(DISTINCT data.did) AS users FROM bluesky WHERE data.kind = 'commit' AND data.commit.operation = 'create' GROUP BY event ORDER BY cnt DESC LIMIT 5 OPTION distinct_precision_threshold=0;
SELECT data.commit.collection AS event, COUNT(*) AS cnt, COUNT(DISTINCT data.did) AS users FROM bluesky WHERE data.kind = 'commit' AND data.commit.operation = 'create' GROUP BY event ORDER BY cnt DESC LIMIT 5 OPTION distinct_precision_threshold=100000000;
SELECT data.did AS u FROM bluesky WHERE data.kind = 'commit' AND data.commit.operation = 'create' AND data.commit.collection = 'app.bsky.feed.post' GROUP BY u LIMIT 1 OPTION max_matches=1000000; SHOW META;
SELECT data.commit.collection AS event, IDIV(BIGINT(data.time_us), 3600000000) % 24 AS hour_of_day, COUNT(*) AS cnt FROM bluesky WHERE data.kind = 'commit' AND data.commit.operation = 'create' AND data.commit.collection IN ('app.bsky.feed.post', 'app.bsky.feed.repost', 'app.bsky.feed.like') GROUP BY event, hour_of_day ORDER BY hour_of_day ASC, event ASC LIMIT 10;
SELECT data.commit.collection AS event, HOUR(IDIV(BIGINT(data.time_us), 1000000)) AS hour_of_day, COUNT(*) AS cnt FROM bluesky WHERE data.kind = 'commit' AND data.commit.operation = 'create' AND ANY(data.commit.collection) IN ('app.bsky.feed.post', 'app.bsky.feed.repost', 'app.bsky.feed.like') GROUP BY event, hour_of_day ORDER BY hour_of_day ASC, event ASC LIMIT 10;
SELECT data.commit.collection AS event, IDIV(BIGINT(data.time_us), 3600000000) % 24 AS hour_of_day, COUNT(*) AS cnt FROM bluesky WHERE data.kind = 'commit' AND data.commit.operation = 'create' AND (data.commit.collection = 'app.bsky.feed.post' OR data.commit.collection = 'app.bsky.feed.repost' OR data.commit.collection = 'app.bsky.feed.like') GROUP BY event, hour_of_day ORDER BY hour_of_day ASC, event ASC LIMIT 10;
SELECT data.did AS user_id, MIN(BIGINT(data.time_us)) AS first_post_ts FROM bluesky WHERE data.kind = 'commit' AND data.commit.operation = 'create' AND data.commit.collection = 'app.bsky.feed.post' GROUP BY user_id ORDER BY first_post_ts ASC LIMIT 3;
SELECT data.did AS user_id, MIN(BIGINT(data.time_us)) AS first_post_ts FROM bluesky WHERE data.kind = 'commit' AND data.commit.operation = 'create' AND data.commit.collection = 'app.bsky.feed.post' GROUP BY user_id ORDER BY first_post_ts ASC LIMIT 3 OPTION max_matches=10000000;
SELECT data.did AS user_id, BIGINT(data.time_us) AS t, MIN(t) AS first_post_ts FROM bluesky WHERE data.kind = 'commit' AND data.commit.operation = 'create' AND data.commit.collection = 'app.bsky.feed.post' GROUP BY user_id ORDER BY first_post_ts ASC LIMIT 3 OPTION max_matches=10000000;
SELECT data.did AS user_id, MIN(BIGINT(data.time_us)) AS first_post_ts FROM bluesky WHERE data.kind = 'commit' AND data.commit.operation = 'create' AND data.commit.collection = 'app.bsky.feed.post' GROUP BY user_id ORDER BY first_post_ts ASC LIMIT 3 OPTION accurate_aggregation=1;
SELECT data.did AS user_id, MIN(BIGINT(data.time_us)) AS first_post_ts FROM bluesky WHERE data.kind = 'commit' AND data.commit.operation = 'create' AND data.commit.collection = 'app.bsky.feed.post' GROUP BY user_id ORDER BY first_post_ts ASC LIMIT 3 OPTION max_matches=1000000000;
SELECT data.did AS user_id, IDIV(MAX(BIGINT(data.time_us)) - MIN(BIGINT(data.time_us)), 1000) AS activity_span FROM bluesky WHERE data.kind = 'commit' AND data.commit.operation = 'create' AND data.commit.collection = 'app.bsky.feed.post' GROUP BY user_id ORDER BY activity_span DESC LIMIT 3 OPTION max_matches=10000000;
SELECT data.did AS user_id, MIN(BIGINT(data.time_us)) AS a, MAX(BIGINT(data.time_us)) AS b, b - a AS activity_span FROM bluesky WHERE data.kind = 'commit' AND data.commit.operation = 'create' AND data.commit.collection = 'app.bsky.feed.post' GROUP BY user_id ORDER BY activity_span DESC LIMIT 3 OPTION max_matches=10000000;
SELECT data.did AS user_id, BIGINT(data.time_us) AS t, MIN(t) AS a, MAX(t) AS b FROM bluesky WHERE data.kind = 'commit' AND data.commit.operation = 'create' AND data.commit.collection = 'app.bsky.feed.post' GROUP BY user_id ORDER BY b DESC LIMIT 3 OPTION max_matches=10000000;
SELECT data.did AS user_id, BIGINT(data.time_us) AS t, MAX(t) - MIN(t) AS activity_span FROM bluesky WHERE data.kind = 'commit' AND data.commit.operation = 'create' AND data.commit.collection = 'app.bsky.feed.post' GROUP BY user_id ORDER BY activity_span DESC LIMIT 3 OPTION max_matches=10000000;
SELECT data.did AS user_id, MIN(BIGINT(data.time_us)) AS a, MAX(BIGINT(data.time_us)) AS b FROM bluesky WHERE data.kind = 'commit' AND data.commit.operation = 'create' AND data.commit.collection = 'app.bsky.feed.post' GROUP BY user_id HAVING b - a > 800000000 LIMIT 5 OPTION max_matches=10000000;
SELECT data FROM bluesky WHERE data.commit.collection = 'app.bsky.feed.post' LIMIT 2;
